#### Encryption at Rest

All sensitive data must be encrypted at rest:

```python
from cryptography.fernet import Fernet
import os

class DataEncryption:
    def __init__(self):
        # Key should be stored in secure key management system
        self.key = os.environ.get("ENCRYPTION_KEY").encode()
        self.cipher = Fernet(self.key)

    def encrypt_sensitive_data(self, data: str) -> str:
        """Encrypt sensitive data before storing"""
        encrypted_data = self.cipher.encrypt(data.encode())
        return encrypted_data.decode()

    def decrypt_sensitive_data(self, encrypted_data: str) -> str:
        """Decrypt sensitive data after retrieving"""
        decrypted_data = self.cipher.decrypt(encrypted_data.encode())
        return decrypted_data.decode()

# Database model with encryption
class Patient(Base):
    __tablename__ = "patients"

    id = Column(String, primary_key=True)
    name = Column(String)  # Non-sensitive data
    _ssn = Column("ssn", String)  # Encrypted field

    @hybrid_property
    def ssn(self):
        if self._ssn:
            return DataEncryption().decrypt_sensitive_data(self._ssn)
        return None

    @ssn.setter
    def ssn(self, value):
        if value:
            self._ssn = DataEncryption().encrypt_sensitive_data(value)
        else:
            self._ssn = None
