#### Output Encoding

Implement proper output encoding to prevent XSS:

```python
import html
import json
from markupsafe import escape

class ResponseFormatter:
    @staticmethod
    def encode_html_output(data: str) -> str:
        """Encode HTML special characters"""
        return html.escape(data)

    @staticmethod
    def encode_json_output(data: dict) -> str:
        """Safely encode JSON output"""
        return json.dumps(data, ensure_ascii=True)

    @staticmethod
    def sanitize_user_content(content: str) -> str:
        """Sanitize user-generated content"""
        # Remove script tags and javascript URLs
        content = re.sub(r'<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>', '', content)
        content = re.sub(r'javascript:', '', content)
        return escape(content)
```

