#### Example 1: Secure API Endpoint

```python
@app.post("/api/v1/patients")
@limiter.limit("20/minute")
async def create_patient(
    request: Request,
    patient_data: CreatePatientRequest,
    current_user: User = Depends(get_current_user)
):
    # Validate user permissions
    if not await auth_service.has_permission(current_user, "patient:create"):
        raise HTTPException(status_code=403, detail="Insufficient permissions")

    # Audit log
    await audit_service.log_action(
        user_id=current_user.id,
        action="patient_create",
        resource="patient",
        details={"patient_id": patient_data.id}
    )

    try:
        patient = await patient_service.create_patient(patient_data)
        return {"status": "success", "patient_id": patient.id}
    except Exception as e:
        await audit_service.log_error(
            user_id=current_user.id,
            action="patient_create_failed",
            error=str(e)
        )
        raise HTTPException(status_code=500, detail="Patient creation failed")
```
